typedef unsigned long машина_Сөз;
static машина_Сөз 동적기억공간[8192];static unsigned 사용량;
void 자바실패(void){const char Текст[]="AOT runtime error\n";жазуу_файл_берилмелер(2,Текст,sizeof(Текст)-1);사용자호출(6,1,0,0,0,0,0);for(;;){}}
void 자바쌓기(машина_Сөз *стек_сактагыч,int *깊이,машина_Сөз маани){if(*깊이<0||*깊이>=128)자바실패();стек_сактагыч[(*깊이)++]=маани;}
машина_Сөз 자바꺼내기(машина_Сөз *стек_сактагыч,int *깊이){if(*깊이<=0||*깊이>128)자바실패();return стек_сактагыч[--*깊이];}
машина_Сөз 자바배열(int 개수){if(개수<0||(unsigned)개수+1>8192-사용량)자바실패();машина_Сөз*자료위치=동적기억공간+사용량;사용량+=개수+1;자료위치[0]=개수;return (машина_Сөз)자료위치;}
машина_Сөз *자바색인(машина_Сөз объект_Шилтемелер,int 개수){машина_Сөз*자료위치=(машина_Сөз*)объект_Шилтемелер;if(!자료위치||개수<0||(машина_Сөз)개수>=자료위치[0])자바실패();return 자료위치+개수+1;}
int 자바길이(машина_Сөз объект_Шилтемелер){if(!объект_Шилтемелер)자바실패();return *(машина_Сөз*)объект_Шилтемелер;}
int 자바나누기(int x_координата,int 세로좌표,int 나머지){if(!세로좌표)자바실패();if(x_координата==(-2147483647-1)&&세로좌표==-1)return 나머지?0:x_координата;return 나머지?x_координата%세로좌표:x_координата/세로좌표;}
static unsigned узундук_маани(const char*сап_берилмелер){unsigned 개수=0;if(!сап_берилмелер)자바실패();while(сап_берилмелер[개수])개수++;return 개수;}
void 자바출력(машина_Сөз 자료위치,int 수치,int 줄바꿈){
    if(수치){char 둘째값[16];unsigned 개수=0;int маани=(int)자료위치;unsigned 부호없는값=маани<0?0-(unsigned)маани:маани;do{둘째값[개수++]='0'+부호없는값%10;부호없는값/=10;}while(부호없는값);if(маани<0)둘째값[개수++]='-';while(개수)жазуу_файл_берилмелер(1,둘째값+--개수,1);}
    else{const char*сап_берилмелер=자료위치?(const char*)자료위치:"null";жазуу_файл_берилмелер(1,сап_берилмелер,узундук_маани(сап_берилмелер));}if(줄바꿈)жазуу_файл_берилмелер(1,"\n",1);
}
машина_Сөз 자바파일쓰기(машина_Сөз ЖОЛ,машина_Сөз маани){const char*сап_берилмелер=(const char*)маани;unsigned 개수=узундук_маани(сап_берилмелер);int файл_тутка=ачуу_файл((const char*)ЖОЛ,쓰기전용|없으면만들기|내용비우기,0600);if(файл_тутка<0)자바실패();int 반환값=жазуу_файл_берилмелер(файл_тутка,сап_берилмелер,개수);жабуу_файл(файл_тутка);if(반환값!=(int)개수)자바실패();return 0;}
машина_Сөз 자바파일읽기(машина_Сөз ЖОЛ){int файл_тутка=ачуу_файл((const char*)ЖОЛ,окуу_үчүн_гана_маани,0);if(файл_тутка<0)자바실패();int 개수=файл_көлөм(файл_тутка);if(개수<0||개수>16384||(unsigned)(개수+8)/8>8192-사용량)자바실패();char*자료위치=(char*)(동적기억공간+사용량);사용량+=(개수+8)/8;int 반환값=파일자료읽기(файл_тутка,자료위치,개수);жабуу_файл(файл_тутка);if(반환값!=개수)자바실패();자료위치[개수]=0;return (машина_Сөз)자료위치;}
